<template>
  <div class="full-width dashboard-list-area duplicate-list-wrapper">
    <q-markup-table
      flat
      :id="tableId"
      v-if="table_columns.length > 0"
      class="dashboard-table-style back-white duplicate-panel-table dashboard-table-header-sticky"
      :class="display_data.length > 0 ? 'dashboard-min-height' : ''"
      :style="{ maxHeight: resolvedTableHeight }"
    >
      <thead>
        <tr class="table-header-text back-white">
          <template v-for="(columnInfo, index) in table_columns" :key="index">
            <th
              class="documnetCol"
            >
              <template v-if="columnInfo.hasOwnProperty('label')">
                <span class="q-pr-md">{{ $t(columnInfo.label) }}</span>
              </template>
              <template v-else>
                {{ $t(columnInfo.name) }}
              </template>
            </th>
          </template>
        </tr>
      </thead>
      <tbody>
        <!-- table rows loop -->
        <tr
          v-for="(row, rowIndex) in display_data"
          :key="row['id']"
          :class="[setRowStyle(row), { 'row-selected': selectedRowId === row.id }]"
          :style="selectedRowId === row.id ? selectedRowStyle : undefined"
          :data-index="rowIndex"
          :id="'row_' + row.id"
        >
          <!-- columns -->
          <template v-for="(columnInfo, index) in table_columns" :key="index">
            <td
              @click="selectAndOpenRow(row)"
              :class="getClassesForColumn(row['status'], columnInfo.name)"
              class="text-weight-regular documnetCol table-body"
            >
              <template v-if="columnInfo.name === 'pages'">
                <span
                  class="q-ml-auto"
                  style="
                    display: flex;
                    justify-content: right;
                    padding-right: 16px;
                  "
                >
                  {{ row[columnInfo.name] ? row[columnInfo.name] : '-' }}
                </span>
                <q-tooltip v-if="row[columnInfo.name]">
                  {{ row[columnInfo.name] }}
                </q-tooltip>
              </template>
              <template v-else-if="columnInfo.name === 'priority'">
                <span style="position: relative; left: 60px">{{
                  row[columnInfo.name] ? row[columnInfo.name] : '-'
                }}</span>
                <q-tooltip v-if="row[columnInfo.name]">{{
                  row[columnInfo.name]
                }}</q-tooltip>
              </template>
              <template v-else-if="columnInfo.name === 'status'">
                <span>
                  <q-badge
                    align="middle"
                    :class="getStatusClass(row['status'])"
                  >
                    <span style="padding: 2px" class="dashboard-status-text">{{
                      getLabelTranslation(row['status'])
                    }}</span>
                  </q-badge>
                  <!-- <span class="q-ml-lg">{{  }}</span> -->
                </span>
                <q-tooltip>
                  {{ getLabelTranslation(row['status']) }}
                </q-tooltip>
                <q-tooltip v-if="row['status'] === 'error'">
                  Click over status to see more details
                </q-tooltip>
              </template>
              <template v-else-if="columnInfo.name === 'doc_type'">
                {{ setDisplayDocType(row) }}
                <q-tooltip>
                  {{ setDisplayDocType(row) }}
                </q-tooltip>
              </template>
              <template
                v-else-if="
                  columnInfo.name === 'total_amount' ||
                  columnInfo.name === 'total_net_amount' ||
                  columnInfo.name === 'net_amount'
                "
              >
                <span class="q-ml-auto" style="padding-right: 16px">
                  {{ row[columnInfo.name] }}
                </span>
                <q-tooltip v-if="row[columnInfo.name]">{{
                  row[columnInfo.name]
                }}</q-tooltip>
              </template>
              <template
                v-else-if="
                  [
                    'created_on',
                    'last_modified_on',
                    'assigned_on',
                    'locked_on',
                  ].indexOf(columnInfo.name) != -1
                "
              >
                {{ formatDateAccordingToPreference(row[columnInfo.name]) }}
                <q-tooltip v-if="row[columnInfo.name]">
                  {{ formatDateAccordingToPreference(row[columnInfo.name]) }}
                </q-tooltip>
              </template>
              <!-- <template v-else-if="columnInfo.name == 'delivery_date' || columnInfo.name == 'invoice_date'">
                  {{ row[columnInfo.name] ? formatDateAccordingToPreference(row[columnInfo.name]) : '-' }}
                  <q-tooltip v-if="row[columnInfo.name]">
                    {{ formatDateAccordingToPreference(row[columnInfo.name]) }}
                  </q-tooltip>
                </template> -->

              <!-- <template v-else>
                  {{ row[columnInfo.name] ? formateDate(row[columnInfo.name]) : '-' }}
                  <q-tooltip v-if="row[columnInfo.name]">{{
                    row[columnInfo.name]
                  }}</q-tooltip>
                </template> -->

              <template v-else>
                {{ row[columnInfo.name] ? row[columnInfo.name] : '-' }}
                <q-tooltip v-if="row[columnInfo.name]">
                  {{ row[columnInfo.name] }}
                </q-tooltip>
              </template>
            </td>
          </template>
        </tr>

        <tr v-if="display_data.length === 0">
          <td class="text-center" :colspan="table_columns.length">
            {{ $t('no_document_found') }}
          </td>
        </tr>
      </tbody>
    </q-markup-table>
  </div>

  <Loader />
</template>

<script lang="ts">
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import docTypeLable from 'src/utils/docTypeLable';
import documentUtil from 'src/utils/documentUtil';
import { ApiExceptions } from 'src/exceptions/index';
import { documentListApiService } from 'src/services';
import { CONSTANTS } from 'src/constants';
import { useUserStore, useDashboardStore } from 'src/store/main';
import DashboardHelper from 'src/pages/Dashboard/DashboardHelper';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'duplicate-document-dlg',
  props: {
    document_ids: {
      type: String,
      default: '',
    },
    tableHeight: {
      type: String,
      default: 'auto',
    },
    // DOCB-10913: the main dashboard list has ALREADY resolved the user's
    // configured columns (including org-specific extracted fields like
    // net_amount/total_amount/invoice_number/delivery_date/supplier_name,
    // each carrying a `doc_type_key`). Re-deriving that same column set
    // from scratch here (via getSavedColumns()/handleTableColumns()) reads
    // the settings store a second time and can come back with the bare
    // built-in defaults if that read is momentarily empty/stale — dropping
    // those fields from the `document_fields` request and leaving the
    // panel showing "-" for values the main list already displays. When
    // the parent passes the already-resolved columns, reuse them instead
    // of re-deriving.
    mainTableColumns: {
      type: Array as any,
      default: () => [],
    },
  },
  components: { Loader },
  mixins: [
    documentUtil,
    docTypeLable,
    dateUtils,
    helperMixin,
    DashboardHelper,
  ],
  data() {
    return {
      tableId: 'duplicate_docs',
    };
  },
  computed: {
    // Falls back to a viewport-bound cap when the parent passes 'auto'
    // (deep-link / first-render case before adjustTableHeightForDuplicate runs)
    resolvedTableHeight(): string {
      return !this.tableHeight || this.tableHeight === 'auto'
        ? '40vh'
        : this.tableHeight;
    },
  },
  mounted: function () {
    this.init();

    document.addEventListener(
      CONSTANTS.dashboard_columns_pref_key + '_updated',
      this.dashboardColumnsEvent,
    );
  },
  unmounted: function () {
    document.removeEventListener(
      CONSTANTS.dashboard_columns_pref_key + '_updated',
      this.dashboardColumnsEvent,
    );
  },
  methods: {
    selectAndOpenRow(row: dynamicObj) {
      this.selectedRowId = row.id;
      console.log('[DOCB-10994] DuplicateDocumentList selectAndOpenRow:', {
        selectedRowId: this.selectedRowId,
        rowId: row.id,
        rowIdType: typeof row.id,
      });
      this.rowClick(row, false, this.isMediUser());
    },
    async init() {
      if (this.mainTableColumns && this.mainTableColumns.length > 0) {
        // Reuse the column set the main dashboard list already resolved
        // (see mainTableColumns prop doc above) instead of re-deriving it.
        this.table_columns = this.mainTableColumns;
      } else {
        await this.getSavedColumns(CONSTANTS.dashboard_columns_pref_key); //not blocking due settings already fetched
        this.table_columns = await this.handleTableColumns(
          false,
          CONSTANTS.dashboard_columns_pref_key,
        );
      }

      this.prepareStatusList();
      this.getDuplicateInvoice();
    },
    // Mirrors dashboard.store.ts's addAdditionalDocTypeFields(), but derives
    // the field list from `this.table_columns` — the exact columns this
    // panel renders — rather than re-reading the settings store. Keeps the
    // requested document_fields and the rendered columns from ever diverging.
    buildDocumentFieldsParam(): string {
      const doc_type_fields = (this.table_columns || [])
        .filter((column: dynamicObj) =>
          column && Object.prototype.hasOwnProperty.call(column, 'doc_type_key'),
        )
        .map((column: dynamicObj) => column.name);

      if (doc_type_fields.length === 0) {
        return '';
      }

      return '&document_fields=' + doc_type_fields.toString();
    },
    async getDuplicateInvoice() {
      if (!this.document_ids) {
        return;
      }
      try {
        this.showLoading();
        let queryParams = '?document_ids=' + this.document_ids;

        queryParams += this.buildDocumentFieldsParam();

        const response = await documentListApiService.getList(queryParams);

        this.display_data = [];
        if (response.documents) {
          this.display_data = response.documents;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async dashboardColumnsEvent() {
      this.table_columns = await this.handleTableColumns(
        true,
        CONSTANTS.dashboard_columns_pref_key,
      );
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();

    const {
      handleTableColumns,
      getSavedColumns,
      addAdditionalDocTypeFields,
    } = dashboard_store;

    const user_store = useUserStore();
    const { isMediUser } = user_store;

    return {
      isMediUser,
      getSavedColumns,
      handleTableColumns,
      addAdditionalDocTypeFields,
      display_data: ref([] as dynamicObj[]),
      table_columns: ref([] as dynamicObj[]),
      selectedRowId: ref<string | null>(null),
      selectedRowStyle: {
        background: 'color-mix(in srgb, var(--primary) 18%, var(--background))',
        boxShadow: 'inset 3px 0 0 0 var(--primary)',
      },
    };
  },
});
</script>

<style lang="scss" scoped>
.duplicate-list-wrapper {
  // Contain the table within the splitter panel; q-markup-table itself
  // already has overflow-y, but lacks horizontal scroll handling.
  max-width: 100%;
  overflow-x: auto;
}

:deep(.duplicate-panel-table) {
  // Ensure the inner scroll container can scroll on both axes when the
  // selected dashboard column set is wider than the panel.
  overflow-x: auto;
  max-width: 100%;
}
</style>
