<template>
  <div class="full-width dashboard-list-area">
    <q-table
      v-if="display_data.length > 0"
      :class="'main-table dashboard-table-style duplicate-panel-table back-white'"
      :style="{ maxHeight: tableHeight }"
      :rows="Object.values(display_data)"
      :rows-per-page-options="[0]"
      :columns="tableColumns"
      row-key="id"
      flat
      hide-bottom
      :no-data-label="$t('no_record_found')"
      id="invoice_table"
    >
      <template v-slot:header="props">
        <q-tr :props="props">
          <q-th
            v-for="col in tableColumns"
            :key="col.name"
            :props="props"
            style="text-align: left"
          >
            <span class="text-item" style="text-transform: capitalize">{{
              $t(col.label)
            }}</span>
          </q-th>
        </q-tr>
      </template>
      <template v-slot:body="props">
        <q-tr
          v-if="!show_table_loader"
          :props="props"
          :class="[setRowStyle(props.row), 'cursor-pointer', { 'row-selected': selectedRowId === props.row.id }]"
          :style="selectedRowId === props.row.id ? selectedRowStyle : undefined"
        >
          <q-td
            v-for="col in props.cols"
            :key="col.name"
            :props="props"
            style="text-align: left"
            @click="selectAndOpenRow(props.row)"
            :class="getClassesForColumn(col.name)"
          >
            <q-badge
              transparent
              v-if="col.name == 'status'"
              align="middle"
              :color="statusColor(col.value)"
            >
              {{ col.value }}
            </q-badge>
            <q-badge
              transparent
              v-else-if="col.value && col.name == 'paid_status'"
              align="middle"
              :color="statusColor(col.value)"
            >
              {{ col.value }}
            </q-badge>
            <div v-else-if="col.name == 'payment_method'">
              {{ showPaymentMethodLabel(col.value) }}
            </div>
            <div v-else-if="col.name == 'electronic_payment_number'">
              {{ displayLastSixDigits(col.value) }}
            </div>
            <div
              v-else-if="col.name == 'extended_amount'"
              align="right"
              style="padding-right: 16px"
            >
              {{ col.value }}
            </div>
            <div v-else-if="dateFields(col.name)">
              {{ formatDateAccordingToPreference(col.value, true) }}
            </div>
            <div v-else class="text-item">{{ col.value }}</div>
          </q-td>
        </q-tr>

        <q-tr v-else>
          <template
            v-for="column_index in tableColumns.length"
            :key="column_index"
          >
            <q-td>
              <div class="box loading-shimmer"></div>
            </q-td>
          </template>
        </q-tr>
      </template>
    </q-table>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { invoiceDashboardStore } from 'src/store/main';
import InvoiceDashboardHelper from 'src/pages/Invoice/page/InvoiceDashboardHelper';

export default defineComponent({
  name: 'duplicate-invoice-dlg',
  props: {
    display_data: {
      type: [] as any,
      default: [],
    },
    tableHeight: {
      type: String,
      default: 'auto',
    },
  },
  components: {},
  mixins: [dateUtils, InvoiceDashboardHelper],
  methods: {
    selectAndOpenRow(row: any) {
      this.selectedRowId = row.id;
      this.goToDetails(row);
    },
  },
  setup() {
    const invoice_store = invoiceDashboardStore();
    const { table_columns } = storeToRefs(invoice_store);

    const tableColumns = ref();
    tableColumns.value = Object.values(
      JSON.parse(JSON.stringify(table_columns.value)),
    ).map((column: any) => {
      return {
        name: column.name,
        required: true,
        order: column.order,
        label: column.translation_key,
        field: column.field,
        actions: column.actions,
      } as dynamicObj;
    });
    tableColumns.value = tableColumns.value.sort(
      (a: any, b: any) => a.order - b.order,
    ) as dynamicObj;

    return {
      tableColumns,
      selectedRowId: ref<string | null>(null),
      selectedRowStyle: {
        background: 'color-mix(in srgb, var(--primary) 18%, var(--background))',
        boxShadow: 'inset 3px 0 0 0 var(--primary)',
      },
    };
  },
});
</script>

<style lang="scss"></style>
